mapper.select:
select l.lot_id, l.lot_no, l.item_id, i.item_cd, i.item_nm, i.unit_cd, i.lot_ctrl_yn, l.hold_yn
  from lot_master l join mst_item i on i.item_id = l.item_id
 where l.lot_no = #{lotNo}

select 
  from mst_equip_hier n left join wms_loc_attr a on a.node_id = n.node_id
 where n.plant_cd = #{plantCd} and n.node_cd = #{nodeCd}

select coalesce(sum(qty), 0) from inv_trx
 where item_id = #{itemId} and node_id = #{nodeId} and lot_id is not distinct from #{lotId}::bigint and stock_status = #{status}
   and occurred_at <= #{at}

mapper.sql:
where s.plant_cd = #{q.plantCd}



            and s.node_id in (with recursive d as (select node_id, 1 as lv from mst_equip_hier where node_id = #{q.nodeId}
                              union all select c.node_id, d.lv + 1 from d join mst_equip_hier c on c.parent_id = d.node_id
                               where d.lv < 20) select node_id from d)

        and s.node_id = #{q.nodeId}


and i.item_cd like #{q.itemCdLike} escape '\'
and i.item_nm ilike #{q.itemNmLike} escape '\'
and s.stock_status = #{q.stockStatus}
and lm.lot_no like #{q.lotNoLike} escape '\'
and s.qty <> 0


where t.occurred_at >= #{q.fromAt} and t.occurred_at < #{q.toAt} and t.plant_cd = #{q.plantCd}
and t.item_id = #{q.itemId}
and i.item_cd like #{q.itemCdLike} escape '\'
and t.node_id = #{q.nodeId}
and t.trx_type = #{q.trxType}

select t.trx_id
  from inv_trx t
  join mst_item i on i.item_id = t.item_id
 where t.occurred_at >= #{q.fromAt} and t.occurred_at < #{q.toAt} and t.plant_cd = #{q.plantCd}
and t.item_id = #{q.itemId}
and i.item_cd like #{q.itemCdLike} escape '\'
and t.node_id = #{q.nodeId}
and t.trx_type = #{q.trxType}

limit #{q.page.size} offset #{q.page.offset}

mapper.select:
select  
 where t.item_id = #{itemId} and t.node_id = #{nodeId} and t.lot_id is not distinct from #{lotId}::bigint
   and t.stock_status = #{status}
 order by t.occurred_at desc, t.trx_id desc
 limit #{limit}

with recursive up as (
    select n.node_id, n.parent_id, 1 as lv from mst_equip_hier n where n.node_id = #{nodeId}
    union all
    select p.node_id, p.parent_id, u.lv + 1 from up u join mst_equip_hier p on p.node_id = u.parent_id where u.lv < 20
)
select exists (select 1 from up join wms_loc_attr a on a.node_id = up.node_id where a.loc_usage = 'SCRAP')
